mapper.select:
WITH all_xfpl AS ( SELECT 0 AS xfpl_code, '春秋装' AS xfpl_name UNION ALL SELECT 1 AS xfpl_code, '夏装' AS xfpl_name UNION ALL SELECT 2 AS xfpl_code, '冬装' AS xfpl_name UNION ALL SELECT 3 AS xfpl_code, '礼服' AS xfpl_name UNION ALL SELECT 4 AS xfpl_code, '运动装' AS xfpl_name UNION ALL SELECT 5 AS xfpl_code, '其他' AS xfpl_name ) SELECT a.xfpl_name AS `key`, COALESCE(t.total_sets, 0) AS value FROM all_xfpl a LEFT JOIN ( SELECT s.XFPL AS xfpl_code, SUM(s.GMTS) AS total_sets FROM XFPT_TEAM_MEETING m INNER JOIN XFPT_TEAM_MEETING_SON s ON m.id = s.TEAM_MEETING_ID
and (m.dept_id = #{deptId} or find_in_set(#{deptId},m.ancestors))
GROUP BY s.XFPL ) t ON a.xfpl_code = t.xfpl_code ORDER BY total_sets DESC;
